#!/usr/bin/env node
// SPDX-License-Identifier: AGPL-3.0-or-later  ·  Copyright (c) 2026 John Chen
// mcd — the minecraft-design toolkit CLI. Pure Node 20+, no install step.
//
//   mcd plan    <file.nbt> --rooms rooms.json [--only name,...]   room floors as character grids, for layers()
//   mcd room    <file.nbt> --rooms rooms.json --only "<room>" [--json]   one room: walk + unreached cells, floor grid,
//               light map, lantern spots that clear the dark (the room designer's check after each rebuild)
//   mcd context <run dir> [--out mcd-context.md]   the shared kit (plan, elements, palette, vocabulary and library
//               outlines) as one text: workers get it in their system prompt, one cached prefix for every session
//   mcd trade   --name "<part name>" [--text "<its spec>"] [--json]   the building trades' cards for that part (at most 2)
//               --all: every card (for the planners)
//   mcd vocab-names <plan.md>   the helper names plan.md's VOCABULARY defines, as JSON (the kit's split)
//   mcd overworld <palette.json> [--write]   nether and end blocks in the palette (--write: drop them), as JSON
//   mcd light   <file.nbt> --rooms rooms.json [--only name,...] | --y <feet y>   light-level map (text; --json summary)
//   mcd rooms   <file.nbt> --rooms rooms.json [--out rooms.png] [--only name,...]   a look into every room
//   mcd render  <file.nbt> [--out sheet.png] [--front n|s|e|w] [--ground y] [--cut y]
